"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[5949],{9229(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/concepts/","label":"Course Overview","docId":"index","unlisted":false},{"type":"category","label":"1. Foundations of Algorithms","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/foundations-of-algorithms/algorithmic-thinking","label":"Algorithmic Thinking","docId":"foundations-of-algorithms/algorithmic-thinking","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/case-study-pairwise","label":"Case Study - Pairwise Product","docId":"foundations-of-algorithms/case-study-pairwise","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/data-structures","label":"Data Structures","docId":"foundations-of-algorithms/data-structures","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/measuring-efficiency","label":"Measuring Efficiency","docId":"foundations-of-algorithms/measuring-efficiency","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/complexity-analysis","label":"Complexity Analysis","docId":"foundations-of-algorithms/complexity-analysis","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/asymptotic-notation","label":"Asymptotic Notation","docId":"foundations-of-algorithms/asymptotic-notation","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/growth-rates","label":"Growth Rates and Predictions","docId":"foundations-of-algorithms/growth-rates","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/complexity-of-loops","label":"Complexity of Loops","docId":"foundations-of-algorithms/complexity-of-loops","unlisted":false},{"type":"link","href":"/concepts/foundations-of-algorithms/searching-case-studies","label":"Searching Case Studies","docId":"foundations-of-algorithms/searching-case-studies","unlisted":false}],"href":"/concepts/category/1-foundations-of-algorithms"},{"type":"category","label":"2. Foundamental Problem Domains","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/foundamental-problem-domains/sorting-algorithms","label":"Foundational Sorting Algorithms","docId":"foundamental-problem-domains/sorting-algorithms","unlisted":false}],"href":"/concepts/category/2-foundamental-problem-domains"},{"type":"category","label":"3. Algorithm Design Paradigms","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/algorithm-design-paradigms/brute-force","label":"Brute Force & Exhaustive Search","docId":"algorithm-design-paradigms/brute-force","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/divide-and-conquer","label":"Divide and Conquer","docId":"algorithm-design-paradigms/divide-and-conquer","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/greedy-algorithms","label":"Greedy Algorithms","docId":"algorithm-design-paradigms/greedy-algorithms","unlisted":false},{"type":"link","href":"/concepts/algorithm-design-paradigms/dynamic-programming","label":"Dynamic Programming","docId":"algorithm-design-paradigms/dynamic-programming","unlisted":false}],"href":"/concepts/category/3-algorithm-design-paradigms"},{"type":"category","label":"4. State Space Search and Optimization","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/state-space-search-and-optimization/backtracking","label":"Backtracking","docId":"state-space-search-and-optimization/backtracking","unlisted":false},{"type":"link","href":"/concepts/state-space-search-and-optimization/branch-and-bound","label":"Branch and Bound","docId":"state-space-search-and-optimization/branch-and-bound","unlisted":false}],"href":"/concepts/category/4-state-space-search-and-optimization"},{"type":"category","label":"5. Advanced Execution Models","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/concepts/advanced-execution-models/parallel-algorithms","label":"Parallel Algorithms & Frameworks","docId":"advanced-execution-models/parallel-algorithms","unlisted":false}],"href":"/concepts/category/5-advanced-execution-models"},{"type":"link","href":"/concepts/glossary","label":"Glossary","docId":"glossary","unlisted":false}]},"docs":{"advanced-execution-models/parallel-algorithms":{"id":"advanced-execution-models/parallel-algorithms","title":"Parallel Algorithms & Frameworks","description":"Up to this point in our computer science curriculum, we have evaluated computational strategies under a sequential execution model, assuming a single central processing unit (CPU) running one machine instruction at a time. However, modern hardware architectures scale processing power by adding physical compute cores rather than raw clock speed.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/brute-force":{"id":"algorithm-design-paradigms/brute-force","title":"Brute Force & Exhaustive Search","description":"When facing a novel computational problem, our immediate priority as engineers is not performance, but correctness. Before we can optimize a solution, we must prove that the problem is solvable.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/divide-and-conquer":{"id":"algorithm-design-paradigms/divide-and-conquer","title":"Divide and Conquer","description":"The Divide and Conquer (D&C) paradigm represents one of the most powerful systemic strategies in algorithm design. Instead of attacking a complex computational problem globally, this approach structurally breaks down problem instances into smaller, homogeneous variants. It fundamentally shifts execution from complex global management to localized resolution and structural combination.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/dynamic-programming":{"id":"algorithm-design-paradigms/dynamic-programming","title":"Dynamic Programming","description":"The Dynamic Programming (DP) paradigm stands as one of the most advanced and elegant optimization frameworks in Computer Science. Its core engineering philosophy can be summarized by a classic software axiom: those who cannot remember the past are condemned to repeat it.","sidebar":"tutorialSidebar"},"algorithm-design-paradigms/greedy-algorithms":{"id":"algorithm-design-paradigms/greedy-algorithms","title":"Greedy Algorithms","description":"Unlike general programming strategies that explore multiple alternative paths, Greedy Algorithms are designed strictly for optimization problems where the goal is to maximize or minimize a specific objective function.","sidebar":"tutorialSidebar"},"foundamental-problem-domains/sorting-algorithms":{"id":"foundamental-problem-domains/sorting-algorithms","title":"Foundational Sorting Algorithms","description":"Sorting is one of the most thoroughly studied problems in Computer Science. At its core, given a structured set of $n$ elements $[a1, a2, a3, \\\\dots, an]$ and a strict total order relation ($\\\\le$), the objective of a sorting algorithm is to rearrange the elements into an increasingly ordered sequence.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/algorithmic-thinking":{"id":"foundations-of-algorithms/algorithmic-thinking","title":"Algorithmic Thinking","description":"In computer science, programming syntax is merely a vehicle for execution. The true engineering core lies in Algorithmics: the systematic study, design and analysis of correct and efficient computational strategies.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/asymptotic-notation":{"id":"foundations-of-algorithms/asymptotic-notation","title":"Asymptotic Notation","description":"In the previous lesson we obtained exact expressions such as $T(n) = 3n + 4$ and saw that the constants depend on arbitrary counting decisions and, in reality, on the machine. What does not depend on them is the rate of growth of the function: how fast $T(n)$ increases when $n$ becomes large.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/case-study-pairwise":{"id":"foundations-of-algorithms/case-study-pairwise","title":"Case Study - Pairwise Product","description":"To truly understand why algorithmics matters, it helps to experience failure first. In this case study we take a deceptively simple problem and solve it again and again. Each version fixes a problem of the previous one, and each fix teaches a different lesson: about the limits of data types, the cost of naive strategies, the impact of data representation, and the danger of \\"optimisations\\" that are not actually correct.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/complexity-analysis":{"id":"foundations-of-algorithms/complexity-analysis","title":"Complexity Analysis","description":"In the previous lesson we saw that measurements depend on the machine, the compiler and the implementation, and that comparing algorithms only by running them has serious limitations. We now develop the alternative: studying the algorithm on paper, by counting how many elementary operations it performs as a function of the size of its input.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/complexity-of-loops":{"id":"foundations-of-algorithms/complexity-of-loops","title":"Complexity of Loops","description":"Most iterative algorithms are, at their core, combinations of loops. Once you can determine quickly and reliably how many times a loop runs, you can analyse almost any iterative program. This lesson collects the most common patterns, explains how to derive each result and points out the traps that appear most often in exams and in real code.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/data-structures":{"id":"foundations-of-algorithms/data-structures","title":"Data Structures","description":"In the previous lessons we saw that the efficiency of a solution depends on the strategy we choose. It also depends, just as much, on how the data is organised in memory. The maximum pairwise product already gave us a hint: the same algorithm used several times more memory with a List than with an int[].","sidebar":"tutorialSidebar"},"foundations-of-algorithms/growth-rates":{"id":"foundations-of-algorithms/growth-rates","title":"Growth Rates and Predictions","description":"Asymptotic notation gives us a precise language. This lesson turns it into practical intuition: what the most common complexity classes mean in real time, how to predict the time an algorithm will need for a larger input, how to estimate the largest input it can handle in a given time, and why no improvement in hardware can change the complexity of an algorithm.","sidebar":"tutorialSidebar"},"foundations-of-algorithms/measuring-efficiency":{"id":"foundations-of-algorithms/measuring-efficiency","title":"Measuring Efficiency","description":"In the case study we compared four strategies for the maximum pairwise product and saw differences ranging from seconds to fractions of a millisecond. But how exactly should we compare algorithms? Is it enough to run them and look at the clock? What should we measure, and how can we trust the numbers?","sidebar":"tutorialSidebar"},"foundations-of-algorithms/searching-case-studies":{"id":"foundations-of-algorithms/searching-case-studies","title":"Searching Case Studies","description":"Searching is one of the most frequent operations in computing: looking up a user in a database, a word in a dictionary, a file in a directory, a value in a cache. In this final lesson of the chapter we apply everything we have learnt to three classic search algorithms. For each one we count instructions exactly, analyse the best, worst and average cases, express the result with asymptotic notation and connect it with real measurements.","sidebar":"tutorialSidebar"},"glossary":{"id":"glossary","title":"Glossary","description":"All concepts defined on this site, grouped by category. Each entry links to its full explanation page.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"Course Overview","description":"Theoretical foundations and design paradigms behind algorithms and data structures.","sidebar":"tutorialSidebar"},"state-space-search-and-optimization/backtracking":{"id":"state-space-search-and-optimization/backtracking","title":"Backtracking","description":"Backtracking is an algorithmic paradigm used to solve problems in which the number of possible candidate solutions is very large, but many of those candidates can be discarded early because they violate some constraint. The central idea is simple: construct a solution step by step, and as soon as a partial solution cannot possibly lead to a valid complete solution, abandon it and return to the previous step.","sidebar":"tutorialSidebar"},"state-space-search-and-optimization/branch-and-bound":{"id":"state-space-search-and-optimization/branch-and-bound","title":"Branch and Bound","description":"When solving hard combinatorial problems, Backtracking provides an exact solution by executing a systematic Depth-First Search (DFS). However, it does so blindly, relying entirely on hitting an unfeasible boundary before turning around.","sidebar":"tutorialSidebar"}}}}')}}]);